def forward(x, layers):
    for W, b, act in layers:
        out = [sum(x[i] * W[i][j] for i in range(len(x))) + b[j] for j in range(len(b))]
        if act == "relu":
            out = [max(0.0, v) for v in out]
        x = out
    return x

import math

def cross_entropy(logits, target):
    m = max(logits)
    lse = m + math.log(sum(math.exp(z - m) for z in logits))
    return -(logits[target] - lse)
